package com.mavric.health.scheduling.application;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.*;
import com.mavric.health.shared.*;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real service/store, offline executor and modeled transaction manager; no HTTP or engine integration. */
class SchedulingServiceSqlServerTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",APPOINTMENT="cc000000-0000-4000-8000-000000000001",OTHER="dd000000-0000-4000-8000-000000000001";
 static final Instant FROM=Instant.parse("2026-11-05T00:00:00.123456Z"),TO=FROM.plusSeconds(86400);
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final Access access=mock(Access.class);final Sql sql=mock(Sql.class);final SchedulingService service=new SchedulingService(new SqlServerSchedulingStore(executor,manager),access);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/appointments");
 SchedulingServiceSqlServerTest(){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ID,c.actorId());assertEquals(TENANT,c.tenantId());return new SqlServerExecutor.Result(List.of(List.of(appointment())),List.of());});}
 void actor(String role,boolean platform){var a=new Actor(ID,"Synthetic","qa@example.test",platform?null:TENANT,List.of(role),"a".repeat(64));doReturn(a).when(access).actor();request.setAttribute("health.actor",a);if(platform)request.removeAttribute("health.tenant");else request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of()));TraceContext.REQUEST.set(request);}
 static Map<String,Object> appointment(){return new LinkedHashMap<>(Map.ofEntries(Map.entry("id",APPOINTMENT),Map.entry("tenantId",TENANT),Map.entry("patientId",OTHER),Map.entry("branchId",OTHER),Map.entry("professionalId",ID),Map.entry("specialtyCode","H_FAMILY"),Map.entry("startsAt",FROM.toString()),Map.entry("endsAt",FROM.plusSeconds(1800).toString()),Map.entry("status","RESERVED"),Map.entry("service","Synthetic"),Map.entry("note","Synthetic note"),Map.entry("revision",1),Map.entry("requestKey","synthetic-key-001"),Map.entry("requestHash",Checks.hash("synthetic-request"))));}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void exactFourReadRolesUseTwoSpAndIgnoreForgedAuthorityHeaders(){for(String role:List.of("REC","PRO","ASI","AUD")){actor(role,false);request.addHeader("X-Roles","SAD");request.addHeader("X-Tenant-Id",ID);request.setContent("forged body authority".getBytes());assertEquals(14,service.list(FROM,TO,null).getFirst().size());assertEquals(14,service.get(APPOINTMENT).size());}verify(access,times(8)).roles("REC","PRO","ASI","AUD");verify(executor,times(4)).execute(eq(SqlServerProcedure.APPOINTMENTS_LIST),any(),eq(FROM),eq(TO),isNull());verify(executor,times(4)).execute(eq(SqlServerProcedure.APPOINTMENT_GET),any(),eq(APPOINTMENT));verify(access,never()).branch(any());verifyNoInteractions(sql);}
 @Test void branchUuidCheckedBeforeAccessAndDenialsStopQuery(){actor("REC",false);assertEquals(400,assertThrows(ApiException.class,()->service.list(FROM,TO,"bad")).status);verify(access,never()).branch(anyString());verifyNoInteractions(executor);assertEquals(1,service.list(FROM,TO,null).size());verify(access,never()).branch(anyString());doAnswer(inv->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());return null;}).when(access).branch(OTHER);service.list(FROM,TO,OTHER);var order=inOrder(access,executor);order.verify(access).branch(OTHER);order.verify(executor).execute(eq(SqlServerProcedure.APPOINTMENTS_LIST),any(),eq(FROM),eq(TO),eq(OTHER));for(int status:List.of(403,404)){doThrow(new ApiException(status,"SAFE","Safe")).when(access).branch(OTHER);assertEquals(status,assertThrows(ApiException.class,()->service.list(FROM,TO,OTHER)).status);}verify(access,times(3)).branch(OTHER);verify(executor,times(2)).execute(any(),any(),any(Object[].class));}
 @Test void missing401PlatformAdmPacAndForgedHostActorFailBeforeSp(){assertEquals(500,assertThrows(ApiException.class,()->service.get(APPOINTMENT)).status);actor("REC",false);doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->service.get(APPOINTMENT)).status);for(String role:List.of("ADM","PAC")){actor(role,false);assertEquals(403,assertThrows(ApiException.class,()->service.list(FROM,TO,null)).status);}actor("SAD",true);assertEquals(403,assertThrows(ApiException.class,()->service.get(APPOINTMENT)).status);actor("REC",false);request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,()->service.get(APPOINTMENT)).status);actor("REC",false);request.setAttribute("health.tenant",new TenantRef(ID,"Other","other","CLINIC","HUMAN","ACTIVE",List.of()));assertEquals(403,assertThrows(ApiException.class,()->service.get(APPOINTMENT)).status);request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,()->service.get(APPOINTMENT)).status);verifyNoInteractions(executor,sql);}
 @Test void getIsTenantWideWithNoBranchModuleOrStatusGate(){actor("AUD",false);doThrow(ApiException.forbidden()).when(access).branch(anyString());assertEquals(OTHER,service.get(APPOINTMENT).get("branchId"));verify(access,never()).branch(anyString());verify(access,never()).write(anyString(),any(String[].class));verify(executor,times(1)).execute(eq(SqlServerProcedure.APPOINTMENT_GET),any(),eq(APPOINTMENT));verifyNoInteractions(sql);}
 @Test void unconvertedWritesGuardBeforeAnyAccessInputsOrSql(){for(Runnable work:List.<Runnable>of(()->service.reserve(null,null,false),()->service.reserve(null,null,true),()->service.change(null,null))){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);}verifyNoInteractions(access,executor,sql);}
 @Test void safeSpErrorsAndCommitFailureDoNotFallback(){actor("PRO",false);doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,51002))).when(executor).execute(any(),any(),any(Object[].class));assertEquals(404,assertThrows(ApiException.class,()->service.get(APPOINTMENT)).status);doReturn(new SqlServerExecutor.Result(List.of(List.of(appointment())),List.of())).when(executor).execute(any(),any(),any(Object[].class));manager.failCommit=true;var e=assertThrows(ApiException.class,()->service.get(APPOINTMENT));assertEquals(500,e.status);assertFalse(e.toString().contains("private"));verify(executor,times(2)).execute(any(),any(),any(Object[].class));verifyNoInteractions(sql);}
 @Test void minimalSpringKeepsLegacyConstructorWithoutDatasourceOrStore(){when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());try(var c=new AnnotationConfigApplicationContext()){c.registerBean(Sql.class,()->sql);c.registerBean(Access.class,()->access);c.registerBean(SchedulingService.class);c.refresh();assertTrue(c.getBean(SchedulingService.class).list(FROM,TO,null).isEmpty());verify(sql).rows(anyString(),any(Object[].class));verify(access).roles("REC","PRO","ASI","AUD");assertEquals(0,c.getBeanNamesForType(SqlServerSchedulingStore.class).length);assertEquals(0,c.getBeanNamesForType(javax.sql.DataSource.class).length);}verifyNoInteractions(executor);}
}
